"use client";
import dynamic from "next/dynamic";
import Prolay from "../components/prolay";
import Authcon, { useAuth } from "../context/authcontext";

const procompo = dynamic(() => import("../components/prolay"), {
  ssr: false,
});
export default function Pro() {
  const { token, role, loading } = useAuth();

  if (loading) {
    return <div className="loading-spinner"> stuff are laoding</div>;
  }

  if (!token) {
    return <p> you have no token</p>;
  }
  console.log(role);
  return (
    <div className="flex justify-center">
      {role === "admin" ? (
        <div className="flex">welcome admin</div>
      ) : (
        <h1> normal user</h1>
      )}
    </div>
  );
}
